package thaumcraft.utility;
import java.util.*;
import com.mojang.serialization.*;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.nbt.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.item.*;
import net.minecraft.world.item.alchemy.PotionContents;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.storage.*;
import net.minecraft.world.phys.AABB;
import thaumcraft.essentia.*;
public final class SprayerEntity extends InventoryDevice implements EssentiaTransport {
 public record State(int version,ItemStack pattern,int charges,Map<String,Integer> recipe,Map<String,Integer> progress,boolean powered){}
 public static final Codec<State> CODEC=RecordCodecBuilder.create(i->i.group(Codec.intRange(1,1).fieldOf("version").forGetter(State::version),ItemStack.OPTIONAL_CODEC.fieldOf("pattern").forGetter(State::pattern),Codec.intRange(0,8).fieldOf("charges").forGetter(State::charges),thaumcraft.alchemy.AspectAmounts.CODEC.fieldOf("recipe").forGetter(State::recipe),thaumcraft.alchemy.AspectAmounts.CODEC.fieldOf("progress").forGetter(State::progress),Codec.BOOL.fieldOf("powered").forGetter(State::powered)).apply(i,State::new));
 private Tag unknown;private ItemStack pattern=ItemStack.EMPTY;private int charges,ticks;private boolean powered;private Map<String,Integer> recipe=Map.of(),progress=Map.of();
 public SprayerEntity(BlockPos p,BlockState s){super(UtilityContent.SPRAYER.get(),p,s);}public boolean supported(){return unknown==null;}public int charges(){return charges;}public Map<String,Integer> recipe(){return recipe;}public Map<String,Integer> progress(){return progress;}public Direction facing(){return getBlockState().getValue(UtilityBlock.FACING);}public boolean accepts(ItemStack s){return s.getItem() instanceof PotionItem&&s.getOrDefault(DataComponents.POTION_CONTENTS,PotionContents.EMPTY).hasEffects();}
 protected void patternChanged(){if(loading||!(level instanceof ServerLevel l)||!supported())return;var now=inventory.getItem(0);if(ItemStack.isSameItemSameComponents(now,pattern))return;pattern=now.copyWithCount(Math.min(1,now.getCount()));charges=0;progress=Map.of();recipe=accepts(pattern)?PotionCosts.recipe(l,pattern):Map.of();sync();}
 public void serverTick(){if(!(level instanceof ServerLevel)||!supported()||isRemoved())return;patternChanged();ticks++;if(ticks%5==0&&accepts(pattern)&&charges<8){if(!recipe.isEmpty()&&thaumcraft.alchemy.AspectAmounts.contains(progress,recipe)){progress=Map.of();charges++;sync();}else {outer:for(int y=0;y<=1;y++)for(var d:Direction.values())if(d!=facing()&&EssentiaNetwork.pull(level,worldPosition.above(y),this,d))break outer;}}
  boolean now=level.hasNeighborSignal(worldPosition);if(now&&!powered&&charges>0)spray();if(now!=powered){powered=now;setChanged();}if(getBlockState().getValue(UtilityBlock.ACTIVE)!=now)level.setBlockAndUpdate(worldPosition,getBlockState().setValue(UtilityBlock.ACTIVE,now));}
 public boolean spray(){if(!(level instanceof ServerLevel l)||!supported()||charges<=0||!accepts(inventory.getItem(0)))return false;patternChanged();if(charges<=0)return false;charges--;var contents=pattern.getOrDefault(DataComponents.POTION_CONTENTS,PotionContents.EMPTY);var p=worldPosition.relative(facing(),2);for(var target:l.getEntitiesOfClass(LivingEntity.class,new AABB(p).inflate(1),e->e.isAlive()&&e.isAffectedByPotions()))contents.applyToLivingEntity(target,1);l.sendParticles(net.minecraft.core.particles.ParticleTypes.CLOUD,worldPosition.getX()+.5+facing().getStepX()*.6,worldPosition.getY()+.5+facing().getStepY()*.6,worldPosition.getZ()+.5+facing().getStepZ()*.6,30,.4,.4,.4,.1);l.playSound(null,worldPosition,net.minecraft.sounds.SoundEvents.LAVA_EXTINGUISH,net.minecraft.sounds.SoundSource.BLOCKS,.25F,2.6F);sync();return true;}
 public String wanted(){if(charges>=8||!accepts(inventory.getItem(0)))return "";return recipe.keySet().stream().sorted().filter(a->progress.getOrDefault(a,0)<recipe.get(a)).findFirst().orElse("");}
 public boolean connects(Direction face){return supported()&&face!=facing();}public boolean canInput(Direction face){return connects(face);}public boolean canOutput(Direction face){return false;}public Map<String,Integer> contents(Direction face){return Map.of();}public String suctionType(Direction face){return wanted();}public int suction(Direction face){return canInput(face)&&!wanted().isEmpty()?128:0;}public int minimumSuction(){return 0;}public boolean insert(String a,Direction face,boolean simulate){if(!canInput(face)||charges>=8||!accepts(inventory.getItem(0))||!ItemStack.isSameItemSameComponents(pattern,inventory.getItem(0))||progress.getOrDefault(a,0)>=recipe.getOrDefault(a,0))return false;if(!simulate){var next=new TreeMap<>(progress);next.merge(a,1,Integer::sum);progress=Map.copyOf(next);sync();}return true;}public boolean extract(String a,Direction f,boolean s){return false;}
 protected void saveAdditional(ValueOutput out){super.saveAdditional(out);if(!loading)patternChanged();if(unknown!=null)out.store("utility",Codec.PASSTHROUGH,new Dynamic<>(NbtOps.INSTANCE,unknown));else out.store("utility",CODEC,new State(1,inventory.getItem(0),charges,recipe,progress,powered));}
 protected void loadAdditional(ValueInput in){super.loadAdditional(in);loading=true;unknown=null;charges=0;recipe=progress=Map.of();pattern=ItemStack.EMPTY;inventory.setItem(0,ItemStack.EMPTY);powered=false;var raw=in.read("utility",Codec.PASSTHROUGH);if(raw.isPresent()){var parsed=CODEC.parse(raw.get()).result();if(parsed.isEmpty())unknown=raw.get().convert(NbtOps.INSTANCE).getValue().copy();else{var s=parsed.get();if(!s.pattern().isEmpty()&&(!accepts(s.pattern())||s.pattern().getCount()!=1)||s.recipe().isEmpty()&&(s.charges()>0||!s.progress().isEmpty())||s.progress().entrySet().stream().anyMatch(e->e.getValue()>s.recipe().getOrDefault(e.getKey(),0)))unknown=raw.get().convert(NbtOps.INSTANCE).getValue().copy();else{pattern=s.pattern().copy();inventory.setItem(0,s.pattern());charges=s.charges();recipe=s.recipe();progress=s.progress();powered=s.powered();}}}loading=false;}
}
